css:
@import url('https://fonts.googleapis.com/css2?family=Cairo:wght@200..1000&family=Cascadia+Mono:ital,wght@0,200..700;1,200..700&family=Noto+Naskh+Arabic:wght@400..700&family=Roboto:ital,wght@0,100..900;1,100..900&family=Ubuntu:ital,wght@0,300;0,400;0,500;0,700;1,300;1,400;1,500;1,700&display=swap');
@page { size: A4; margin: 10mm 8mm 10mm 8mm; }
html, body { margin: 0; padding: 0; }
body { font-family: 'Ubuntu', sans-serif; color: #111; }
.page { width: 180mm; margin: 0 auto; page-break-after: always; }
.header-section, .footer-section { width: 100%; display: flex; justify-content: space-between; align-items: center; }
.header-section { border-bottom: 1px solid #ccc; display: table; width: 100%; }
.header-section .logo-container { display: table-cell; width: 25%; vertical-align: middle; }
.logo { width: 110px; height: auto; }
.company-names { text-align: right; display: table-cell; width: 75%; vertical-align: middle; }
.company-names .en { margin: 0; font-size: 16px; font-family: 'Roboto', sans-serif; color: #000; }
.company-names .ar { margin: 0; font-size: 22px; font-family: 'Cascadia Mono', monospace; font-weight: 500; color: #000; direction: rtl; }
.page-content { padding: 8mm 5mm; font-size: 14px; line-height: 1.4; }
.footer-section { flex-direction: row-reverse; font-size: 12px; color: hsl(0, 0%, 27%); margin-top: 10px; }
.footer-section .ar { direction: rtl; text-align: right; flex: 1; }
.footer-section .en { direction: ltr; text-align: left; flex: 1; }
.bi-row { width: 100%; max-width: 520px; margin: 0 auto; display: flex; justify-content: space-between; align-items: baseline; gap: 12px; }
.bi-row .en, .bi-row .ar { font-weight: 900; }
.sec { margin-top: 8px; page-break-inside: avoid; }
.sec-h { margin: 0 0 4px 0; }
table.tbl, table.meta-table { width: 100%; border-collapse: collapse; table-layout: fixed; }
table.meta-table th { font-family: 'Ubuntu'; border: 0; text-align: left; background-color: #efdfdf; font-weight: 300; color: #07417b; }
table.meta-table td, table.meta-table th, table.tbl td, table.tbl th { padding: 4px 6px; vertical-align: top; line-height: 1.3; }
table.tbl th { font-weight: 900; font-size: 10.5px; color: #333; border-bottom: 1px solid #eaeaea; }
table.tbl td { border-bottom: 1px solid #f1f1f1; word-wrap: break-word; }
table.tbl tr:last-child td { border-bottom: 0; }
.col-item { width: 38%; }
.col-yes { width: 10%; text-align: center; font-weight: 900; }
.col-no { width: 10%; text-align: center; font-weight: 900; }
.col-notes { width: 22%; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.col-category { width: 20%; }
.th-bi { display: block; line-height: 1.05; text-align: center; }
.th-bi .en { display: block; font-weight: 900; font-size: 10.2px; margin: 0; }
.th-bi .ar { display: block; font-weight: 900; font-size: 10.6px; margin: 0; direction: rtl; }
.small { font-size: 10px; color: #333; }
